INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (11114, 'ባለ ትልቅ ራሱ ጉንዳንና ሰነፏ እርግብ', 'am', 'ጠንክረው የሚሠሩ ነገሥታት ሊሆኑ ይችላሉ። በደንብ የሚዘፍኑ ደግሞ ነገሥታትን ማሳ Nível: First words. Ilustração: Joe  Werna.', 'http://africanstorybook.org/illustrations/covers/39460.png', NULL, 1130, 23, 18, 'asp-39460', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (11115, 'ቡናማ', 'am', 'ይህ መጽሐፍ ገላጭ ዓረፍተ ነገሮችን ከየዕለት የቡናማ ነገሮች ፎቶግራፎች ጋር ያካትታል። Nível: First words. Ilustração: Sue Kramer.', 'http://africanstorybook.org/illustrations/covers/39462.png', NULL, 1130, 23, 18, 'asp-39462', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (11116, 'ቦቢ ወደቀ', 'am', 'ቦቢ ጥንቸል ሲያባርር ትልቅ ጉድጓድ ውስጥ ወደቀ። ይህ ቀላል ታሪክ በአጫጭር ዓረፍተ ነገሮች የተዋቀረ ነው። ይህ መጽሐፍ እ.ኤ. አ. በ2022 የአፍሪካ የተረት መጽሐፍ መርሐግብር፣ ብሪቲሽ ካውንስል (ደቡብ አፍሪካ) እና የመሠረታዊ ትምህርት ክፍልን ያካተተ የትብብር ፕሮጀክት አካል ሆኖ ተዘጋጀ ነው፡፡ Nível: First sentences. Ilustração: Martin  Letsoalo.', 'http://africanstorybook.org/illustrations/covers/39464.png', NULL, 1130, 23, 18, 'asp-39464', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (11117, 'ባተሌ ባተሌዋ ፀሐይ', 'am', 'ይህ ታሪክ ፀሐይ በአንድ ታዳጊ ልጅ ዓይን ከጠዋት ጀምሮ እስከ ምሽት ድረስ የምትታይበትን መንገድ ይተርካል። Nível: First sentences. Ilustração: Joe  Werna.', 'http://africanstorybook.org/illustrations/covers/39465.png', NULL, 1130, 23, 18, 'asp-39465', 'cc-by', 0, NULL);
